        align-items: center;
        justify-content: center;
        z-index: 9999;
        transition: all 0.3s ease-in-out;
        }

        .ad-popup-box {
        position: relative;
        max-width: 450px;
        width: 85%;
        background: #fff;
        padding: 8px; 
        border-radius: 15px; 
        transform: scale(0.7); 
        transition: transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
        }

        .ad-popup-overlay.active {
        display: flex;
        }
        .ad-popup-overlay.active .ad-popup-box {
        transform: scale(1);
        }

        .ad-image-wrapper {
        position: relative;
        overflow: hidden;
        border-radius: 10px;
        }

        .ad-popup-box img {
        width: 100%;
        height: auto;
        display: block;
        transition: transform 0.5s ease;
        }

        /* Close Button */
        .ad-popup-close {
        position: absolute;
        top: -15px;
        right: -15px;
        background: #ff4757; 
        color: #fff;
        border: 3px solid #fff;
        width: 36px;
        height: 36px;
        font-size: 22px;
        font-weight: bold;
        cursor: pointer;
        border-radius: 50%;
        box-shadow: 0 4px 10px rgba(0,0,0,0.3);
        display: flex;
        align-items: center;
        justify-content: center;
        z-index: 10;
        transition: background 0.2s;
        }

        .ad-popup-close:hover {
        background: #ff6b81;
        }

        /* Image Hover Effect */
        .ad-link:hover img {
